#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long K;
    long long R0, L0;
    if(!(cin >> K >> R0 >> L0)) return 0;
    double P, E, T;
    if(!(cin >> P)) return 0;
    if(!(cin >> E)) return 0;
    if(!(cin >> T)) return 0;

    double W = (double)L0 - (double)R0; // initial width
    long long N = 1LL << K; // number of leaves

    cout.setf(std::ios::fixed); cout<<setprecision(10);

    // Degenerate case: width is zero -> T' is constant
    if (W == 0.0) {
        double Tprime = (double)R0;
        double diff = fabs(T - Tprime);
        double ans = (diff <= E + 1e-12) ? 1.0 : 0.0;
        cout << ans << "\n";
        return 0;
    }

    double S = W / (double)N; // spacing between consecutive leaf centers

    // Compute range of leaf indices whose centers lie within [T-E, T+E]
    double jmin_d = (T - E - (double)R0) / S - 0.5;
    double jmax_d = (T + E - (double)R0) / S - 0.5;
    long long j_min = (long long)ceil(jmin_d - 1e-12);
    long long j_max = (long long)floor(jmax_d + 1e-12);
    if (j_min < 0) j_min = 0;
    if (j_max > N - 1) j_max = N - 1;
    if (j_min > j_max) {
        cout << 0.0 << "\n";
        return 0;
    }

    double ans = 0.0;

    // DFS over implicit binary tree of depth K
    function<void(long long,long long,double)> dfs = [&](long long start, long long end, double mass) {
        if (end <= j_min || start > j_max) return; // no overlap
        // fully inside the target leaf range
        if (start >= j_min && end - 1 <= j_max) {
            ans += mass;
            return;
        }
        long long mid = (start + end) >> 1;
        // center of the current node's interval
        // left end = R0 + start * S, right end = R0 + end * S
        // center c = (left + right) / 2 = R0 + (start + end) / 2 * S
        double c = (double)R0 + ((double)(start + end) * 0.5) * S;
        double p_left = (T <= c) ? (1.0 - P) : P; // probability to go to left child
        double p_right = 1.0 - p_left;
        dfs(start, mid, mass * p_left);
        dfs(mid, end, mass * p_right);
    };

    dfs(0, N, 1.0);
    cout << ans << "\n";
    return 0;
}
